package com.opensocket.aievent.core.capability.runtime;
import java.time.Duration;import java.util.Set;import org.springframework.core.env.Environment;import org.springframework.stereotype.Component;import com.opensocket.aievent.core.configuration.runtime.*;
@Component public final class SemanticTriageRuntimeConfigurationView {public static final String SET_KEY=RuntimeConfigurationSetKeys.CAPABILITY_OPERATIONAL_SYSTEM;public static final String WORKER_DELAY_MS="opendispatch.stage10.semantic-triage.worker-delay-ms";public static final Set<String> ALL=Set.of(WORKER_DELAY_MS);private final RuntimeConfigurationSnapshotValues values;private final RuntimeConfigurationAuthorityRegistry authority;private final Environment startup;public SemanticTriageRuntimeConfigurationView(RuntimeConfigurationSnapshotValues v,RuntimeConfigurationAuthorityRegistry a,Environment s){values=v;authority=a;startup=s;}public Duration workerDelay(){long v;if(authority!=null&&authority.isRuntimeAuthoritative(WORKER_DELAY_MS)){if(!values.hasSnapshot(SET_KEY))throw inc();values.requireKeys(SET_KEY,ALL);v=values.longValue(SET_KEY,WORKER_DELAY_MS).orElseThrow(SemanticTriageRuntimeConfigurationView::inc);}else v=values.longValue(SET_KEY,WORKER_DELAY_MS).orElse(startup.getProperty(WORKER_DELAY_MS,Long.class,5000L));if(v<100||v>3600000)throw new IllegalStateException("RUNTIME_CONFIG_VALIDATION_FAILED key="+WORKER_DELAY_MS+" value="+v);return Duration.ofMillis(v);}private static IllegalStateException inc(){return new IllegalStateException("CONFIGURATION_INCOMPLETE setKey="+SET_KEY+" key="+WORKER_DELAY_MS);}}
